begin;
do $test$ declare a uuid:=gen_random_uuid();p uuid:=gen_random_uuid();c uuid:=gen_random_uuid();v uuid;t uuid;e uuid;ann uuid;begin
 insert into auth.users(id,email,email_confirmed_at) values(a,a||'@example.invalid',now()),(p,p||'@example.invalid',now()),(c,c||'@example.invalid',now());
 insert into public.team_memberships values(a,'administrator'),(p,'parent'),(c,'coach');
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 insert into public.tournament_vendors(organization,contact_name,phone) values('Vendor QA '||a,'Private QA','555-0100') returning id into v;
 update public.tournament_vendors set archived=true where id=v;
 if (select version from public.tournament_vendors where id=v)<>2 then raise exception 'Vendor version not advanced';end if;
 if (select count(*) from public.tournament_vendor_history where vendor_id=v)<>2 then raise exception 'Vendor audit missing';end if;
 insert into public.team_tournaments(name,vendor_id,cost_cents,notes) values('Tournament planning QA',v,19000,'PRIVATE COST NOTES') returning id into t;
 begin perform public.publish_tournament(t,1);raise exception 'Incomplete draft published';exception when raise_exception then if sqlerrm not like 'Choose Registered%' then raise;end if;end;
 if exists(select 1 from public.team_events where tournament_id=t) then raise exception 'Draft visible on calendar';end if;
 update public.team_tournaments set planning_status='confirmed',event_date='2026-11-14',end_date='2026-11-15',start_time='09:00',location='QA gym',version=2 where id=t;
 perform public.publish_tournament(t,2);
 if (select count(*) from public.team_events where tournament_id=t and not cancelled)<>2 then raise exception 'Weekend calendar entries missing';end if;
 select id into e from public.team_events where tournament_id=t and tournament_day=0;
 begin perform public.publish_tournament(t,2);raise exception 'Stale publication accepted';exception when raise_exception then if sqlerrm not like 'Tournament changed%' then raise;end if;end;
 update public.team_tournaments set event_date='2026-11-21',end_date='2026-11-22',location='Updated QA gym',version=version+1 where id=t;
 if not exists(select 1 from public.team_events where id=e and date='2026-11-21' and location='Updated QA gym') then raise exception 'Calendar edit lost event identity';end if;
 update public.team_tournaments set end_date='2026-11-21',version=version+1 where id=t;
 if (select count(*) from public.team_events where tournament_id=t and cancelled)<>1 then raise exception 'Removed tournament day not cancelled';end if;
 update public.team_tournaments set planning_status='cancelled',version=version+1 where id=t;
 if exists(select 1 from public.team_events where tournament_id=t and not cancelled) then raise exception 'Tournament cancellation not synced';end if;
 update public.team_tournaments set planning_status='confirmed',version=version+1 where id=t;
 update public.team_tournaments set archived=true,version=version+1 where id=t;
 if exists(select 1 from public.team_events where tournament_id=t and not cancelled) then raise exception 'Archive did not cancel events';end if;
 update public.team_tournaments set archived=false,version=version+1 where id=t;
 if (select count(*) from public.team_events where tournament_id=t and not cancelled)<>1 then raise exception 'Restore failed';end if;
 begin update public.team_events set location='Bypass QA' where id=e;raise exception 'Linked event bypassed planner';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',p::text,true);
 if exists(select 1 from public.tournament_vendors) or exists(select 1 from public.tournament_vendor_history) or exists(select 1 from public.team_tournaments) then raise exception 'Parent can read private administration data';end if;
 if not exists(select 1 from public.team_events where id=e and title='Tournament planning QA') then raise exception 'Published event not visible to parent';end if;
 begin perform public.publish_tournament(t,6);raise exception 'Parent published';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',c::text,true);
 if exists(select 1 from public.tournament_vendors) then raise exception 'Coach can read vendor directory';end if;
 begin insert into public.tournament_vendors(organization) values('Unauthorized QA');raise exception 'Coach created vendor';exception when insufficient_privilege then null;end;
 begin perform public.publish_tournament(t,6);raise exception 'Coach published';exception when insufficient_privilege then null;end;
 begin delete from public.team_events where id=e;raise exception 'Coach deleted linked event';exception when insufficient_privilege then null;end;
 reset role;
end $test$;
rollback;
